# Generated by GitHub Copilot - Oct-05-2026
def _quantile(values, fraction):
    """Return an observed distribution quantile, or null for absent measurements."""
    ordered = sorted(values)
    if not ordered:
        return None
    position = (len(ordered) - 1) * fraction
    lower = int(position)
    upper = min(lower + 1, len(ordered) - 1)
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)


# Generated by GitHub Copilot - Oct-05-2026
def _embedding(rows):
    """Aggregate compatible finite samples robustly; never average dimensions."""
    samples = defaultdict(list)
    for row in rows:
        value = row.get("face_embedding")
        if value is None:
            continue
        vector = np.asarray(value, dtype=float).reshape(-1)
        norm = float(np.linalg.norm(vector))
        if 1 < len(vector) <= 4096 and np.isfinite(vector).all() and norm > 1e-8:
            samples[len(vector)].append(vector / norm)
    if not samples:
        return None
    vectors = max(samples.values(), key=len)
    if len(vectors) > 32:
        vectors = [vectors[index] for index in np.linspace(0, len(vectors) - 1, 32, dtype=int)]
    template = np.median(np.stack(vectors), axis=0)
    norm = float(np.linalg.norm(template))
    return template / norm if norm > 1e-8 else None


# Generated by GitHub Copilot - Oct-05-2026
def _buckets(vector):
    """Use deterministic banded signs to bound candidate retrieval on long videos."""
    size = len(vector)
    for band in range(4):
        indices = [(band * 29 + offset * 17) % size for offset in range(8)]
        yield size, band, tuple(bool(vector[index] >= 0) for index in indices)


# Generated by GitHub Copilot - Oct-05-2026
def _face_neighbors(vector, people, limit=12):
    """Exact, bounded cosine retrieval; never uses appearance, screen position or identity names.

    Returns candidates plus the nearest competitor(s), so a weak indexed match
    cannot win simply because a stronger face fell on another hash boundary.
    The identity count bound prevents adversarial inputs from exhausting memory.
    """
    valid = [(pid, person["template"]) for pid, person in people.items()
             if person.get("template") is not None and len(person["template"]) == len(vector)]
    if not valid or len(valid) > 2500:
        return []
    matrix = np.stack([value for _, value in valid])
    scores = matrix @ vector
    positions = np.argsort(-scores, kind="stable")[:max(2, min(int(limit), len(valid)))]
    return [(float(scores[index]), valid[index][0]) for index in positions
            if np.isfinite(scores[index])]


def _conflict(track, person):
    """Never merge simultaneous tracklets, including observations on one frame."""
    for interval in person["intervals"]:
        if track["first_seen"] <= interval[1] and interval[0] <= track["last_seen"]:
            return True
    return False


