def apply_person_identities(vision, reid):
    """Project persistent IDs for downstream consumers, retaining all raw tracklets."""
    mapping = reid.get("tracklet_to_person", {})
    observations = []
    by_time = defaultdict(set)
    for row in vision.get("observations", []):
        person_id = mapping.get(row.get("track_id"))
        if person_id:
            observations.append({**row, "raw_person_id": row.get("person_id"),
                                 "person_id": person_id, "persistent_person_id": person_id,
                                 "tracklet_id": row.get("track_id")})
            by_time[row["time"]].add(person_id)
    return {**vision, "raw_people": vision.get("people", []),
            "tracklet_observations": vision.get("observations", []),
            "people": reid.get("identities", []), "observations": observations,
            "frames": [{**frame, "raw_visible_people": frame.get("visible_people", []),
                        "visible_people": sorted(by_time[frame["time"]])} for frame in vision.get("frames", [])],
            "tracking_metrics": reid.get("metrics", {})}
